import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Teorema della rovina del giocatore","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/ld/lde.md","filePath":"lezioni/l_calcolo-delle-probabilita/ld/lde.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/ld/lde.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="teorema-della-rovina-del-giocatore" tabindex="-1">Teorema della rovina del giocatore <a class="header-anchor" href="#teorema-della-rovina-del-giocatore" aria-label="Permalink to “Teorema della rovina del giocatore”">​</a></h1><p>Vale il seguente teorema:</p><blockquote><p><strong>In un gioco equo contro un banco illimitato ogni giocatore è destinato a perdere</strong></p></blockquote><p>Vediamo di capire cosa significa e perché succede: Consideriamo un gioco equo, tipo ad esempio il lancio di una moneta: Se esce testa vinciamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> euro, se esce croce perdiamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> euro; Sappiamo che all&#39;aumentare delle prove fatte la frequenza si avvicina al valore della probabilità; però lo scarto tra le uscite di testa e di croce aumenta comunque;</p><p>Quando il gioco si sviluppa, quindi, la linea del guadagno e delle perdite ([in blu]{.text-blue}), a causa degli scarti, oscilla attorno alla linea del guadagno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> (essendo il gioco equo) ma le oscillazioni possono essere più o meno ampie: non appena una linea abbastanza ampia supera la [disponibilità del giocatore (in rosso)]{.text-red} il giocatore ha perso tutto, mentre il banco, avendo possibilità illimitate, continuerà sempre a giocare.</p><p>Ancora peggio sarà per il giocatore nel gioco organizzato in quanto il guadagno costante del banco rende la retta &quot;guadagno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>&quot; inclinata (l&#39;inclinazione della retta &quot;guadagno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>&quot; per il giocatore sarà tanto maggiore quanto maggiore è la percentuale di guadagno del banco).</p><p>In questo caso, come puoi vedere dal grafico, il giocatore è destinato a perdere più velocemente perché gli scarti si sviluppano attorno alla retta nera che, stavolta, è obliqua.</p><blockquote><p><strong>Nota:</strong> Come puoi vedere l&#39;unico sistema per non perdere sistematicamente al gioco è giocare con un amico ed alle stesse probabilità (gioco equo). Se vuoi provare una volta a giocare ad un gioco organizzato allora ti conviene fare un&#39;unica puntata e poi, comunque vada, smettere di giocare. Se non altro limiterai le perdite.</p><p>Ricordo una volta che, entrato in un bar con un amico, costui, dopo pagate le consumazioni, chiese un gratta e vinci da <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn></mrow><annotation encoding="application/x-tex">5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> euro e, grattando, vinse la somma di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn></mrow><annotation encoding="application/x-tex">5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> euro. Presentò il tagliando al negoziante che, pronto, gli porse un altro gratta e vinci, ma il mio amico: &quot;No, grazie, preferisco i <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn></mrow><annotation encoding="application/x-tex">5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> euro&quot; Intascò il denaro ed uscimmo dal bar.</p></blockquote>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};